import json, sys, time, urllib.request, urllib.error
from datetime import datetime, timezone

BASE = "http://localhost:8080"
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive: 31 May inclusive

log_count = {"429": 0, "401": 0, "5xx": 0, "other": 0}

def request(method, path, token=None, retries=20):
    headers = {}
    if token:
        headers["Authorization"] = "Bearer " + token
    last = None
    for attempt in range(retries):
        req = urllib.request.Request(BASE + path, method=method, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return json.loads(r.read().decode())
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors="replace")
            last = (e.code, body)
            if e.code == 429:
                log_count["429"] += 1
                wait = e.headers.get("Retry-After")
                try:
                    delay = float(wait) if wait else None
                except ValueError:
                    delay = None
                if delay is None:
                    try:
                        delay = float(json.loads(body).get("retry_after", 1))
                    except Exception:
                        delay = 1.0
                time.sleep(delay)
                continue
            if e.code == 401 and token is not None:
                log_count["401"] += 1
                raise TokenExpired()
            if 500 <= e.code < 600:
                log_count["5xx"] += 1
                time.sleep(min(2 ** attempt, 10))
                continue
            log_count["other"] += 1
            if e.code == 404:
                return None
            time.sleep(1)
            continue
        except (urllib.error.URLError, TimeoutError, ConnectionError):
            log_count["other"] += 1
            time.sleep(min(2 ** attempt, 10))
            continue
    raise RuntimeError(f"gave up on {path}: {last}")

class TokenExpired(Exception):
    pass

def get_token():
    return request("POST", "/token")["token"]

def authed_get(path, state):
    while True:
        try:
            return request("GET", path, token=state["token"])
        except TokenExpired:
            state["token"] = get_token()

def parse_ts(s):
    return datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(timezone.utc)

def discounted(amount, pct):
    # round half up to whole cent, per order
    num = amount * (100 - pct)
    q, r = divmod(num, 100)
    if r * 2 >= 100:
        q += 1
    return q

def main():
    state = {"token": get_token()}
    seen = {}
    duplicates = 0
    all_pages = []
    page = 1
    total_pages = None
    next_path = "/orders?page=1"
    while next_path:
        data = authed_get(next_path, state)
        all_pages.append(data["page"])
        total_pages = data["total_pages"]
        for o in data["items"]:
            if o["id"] in seen:
                duplicates += 1
                if seen[o["id"]] != o:
                    print("WARNING: differing duplicate for", o["id"], file=sys.stderr)
                continue
            seen[o["id"]] = o
        next_path = data.get("next")
    if sorted(all_pages) != list(range(1, total_pages + 1)):
        print("PAGE MISMATCH", all_pages, total_pages, file=sys.stderr)

    customers = {}
    total = 0
    by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
    count = 0
    status_counts = {}
    for oid, o in seen.items():
        status_counts[o["status"]] = status_counts.get(o["status"], 0) + 1
        if o["status"] != "shipped":
            continue
        ts = parse_ts(o["placed_at"])
        if not (START <= ts < END):
            continue
        cid = o["customer_id"]
        if cid not in customers:
            c = authed_get(f"/customers/{cid}", state)
            if c is None:
                raise RuntimeError(f"unknown customer {cid} for {oid}")
            customers[cid] = c
        c = customers[cid]
        amt = discounted(o["amount_cents"], c["discount_pct"])
        total += amt
        by_region[c["region"]] += amt
        count += 1

    result = {
        "total_cents": total,
        "order_count": count,
        "duplicates_skipped": duplicates,
        "by_region": by_region,
    }
    print(json.dumps(result, indent=2))
    print("pages:", total_pages, "distinct orders:", len(seen), "statuses:", status_counts,
          "customers fetched:", len(customers), "retries:", log_count, file=sys.stderr)
    with open("/workspace/result.json", "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")

if __name__ == "__main__":
    main()
